{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "자전거 주차장에 같은 자전거가 아홉 날째 그대로 있을 때, 열흘 가까이 됐으니 구청에서 바로 치워 버려도 되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청이 바로 치워 버릴 수 있는 것은 아니다. 조례 제10조제2항에 따르면 구청장은 주차 후 동일 장소에 무단으로 10일 이상 방치된 자전거에 대하여 소유자나 위탁자에게 무단방치 여부를 확인하고, 무단방치로 판명된 때에만 법 제20조 및 영 제11조에 따라 처분할 수 있다. 따라서 아홉 날째인 현재는 10일 이상 방치 요건을 충족하지 않아 이 조항에 따른 처분 대상이 아니다.",
          "b_ids": "자전거:제10조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
